#!/bin/bash
set -uo pipefail
echo "=== HEAD ==="; git rev-parse HEAD | cut -c1-11
mkdir -p src/v2/test/claim/manual
echo '' | base64 -d > src/v2/test/claim/manual/data_decl_layout_probe_tmp.dag
cargo build --release -p v1-compiler --bin claim_batch 2>&1 | tail -1
./target/release/claim_batch --source-root src --source-root src/v1 --source-root src/v2 --source-root dag   --entry src/v2/test/claim/manual/data_decl_layout_probe_tmp.dag --function data_decl_layout_parity_probe_reports > /tmp/pb.log 2>&1
echo "probe rc=$?"
echo "=== OBSERVATION ==="
grep -aE 'DATA-LAYOUT-PROBE|^joined:|^continuation:|^blank:|^dangling:|joined: |continuation: |blank: |dangling: |resolve failed|error:' /tmp/pb.log | head -14 | cut -c1-230
rm -f src/v2/test/claim/manual/data_decl_layout_probe_tmp.dag
echo "=== DONE ==="
